// One search rule for the partner's service list on web and app: every word typed starts a word of the name or description, in any order; plurals count.
const words = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
const stem = (w) => (w.length > 3 ? w.replace(/(es|s)$/, '') : w);

export function matchesService(line, query) {
  const typed = words(query);
  if (!typed.length) return true;
  const hay = words(`${line?.name || ''} ${line?.description || ''}`);
  return typed.every((t) => hay.some((h) => h.startsWith(t) || h.startsWith(stem(t)) || (t.length >= 4 && h.includes(stem(t)))));
}

// The services to show for what was typed; ones already ticked always stay so a choice never disappears.
export function searchServices(lines, query, picked = []) {
  if (!words(query).length) return lines;
  return (lines || []).filter((l) => picked.includes(l.code) || matchesService(l, query));
}
